        d2 = json.loads(str(resp))
        return d2 if isinstance(d2, dict) else {}
    except Exception:
        return {}

def iter_urls_in_obj(obj: Any, max_depth: int = 6, max_urls: int = 200) -> List[str]:
    out: List[str] = []
    seen = set()

    def add(u: str) -> None:
        if u in seen:
            return
        seen.add(u)
        out.append(u)

    def walk(x: Any, depth: int) -> None:
        if len(out) >= max_urls:
            return
        if depth > max_depth:
            return
        if is_url(x):
            add(x)
            return
        if isinstance(x, dict):
            for k, v in x.items():
                if isinstance(k, str) and is_url(k):
                    add(k)
                walk(v, depth + 1)
                if len(out) >= max_urls:
                    return
        elif isinstance(x, list):
            for it in x:
                walk(it, depth + 1)
                if len(out) >= max_urls:
                    return
        elif isinstance(x, tuple):
            for it in x:
                walk(it, depth + 1)
                if len(out) >= max_urls:
                    return

    walk(obj, 0)
    return out

def extract_text_from_response_dict(d: Dict[str, Any]) -> str:
    if isinstance(d.get("output_text"), str):
        return d["output_text"]
    output = d.get("output")
    if not isinstance(output, list):
        return ""
    parts: List[str] = []
    for item in output:
        if not isinstance(item, dict):
            continue
        t = item.get("type")
        if t in ("output_text", "text"):
            txt = item.get("text")
            if isinstance(txt, str):
                parts.append(txt)
            continue
        if t == "message":
            content = item.get("content")
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get("type") in ("output_text", "text"):
                        txt2 = c.get("text")
                        if isinstance(txt2, str):
                            parts.append(txt2)
    return "".join(parts)

def extract_urls_from_response(resp: Any) -> List[str]:
    d = model_dump_any(resp)
    urls: List[str] = []
    c = d.get("citations")
    if isinstance(c, list):
        for item in c:
            if isinstance(item, dict):
                u = item.get("url") or item.get("source") or item.get("link")
                if is_url(u):
                    urls.append(u)
            elif is_url(item):
                urls.append(item)
    output = d.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "message":
                content = item.get("content")
                if isinstance(content, list):
                    for c2 in content:
                        if not isinstance(c2, dict):
                            continue
                        ann = c2.get("annotations")
                        if isinstance(ann, list):
                            for a in ann:
                                if isinstance(a, dict):
                                    u = a.get("url")
                                    if is_url(u):
                                        urls.append(u)
                                    u2 = a.get("source")
                                    if is_url(u2):
                                        urls.append(u2)
            if item.get("type") in ("web_search_call", "websearch_call", "tool_call"):
                urls.extend(iter_urls_in_obj(item, max_depth=6, max_urls=200))
    urls.extend(iter_urls_in_obj(d, max_depth=5, max_urls=200))
    urls = [u for u in urls if is_url(u)]
    return list(dict.fromkeys(urls))

