        obj["sources"] = []
    obj["sources"] = [u for u in obj["sources"] if is_url(u)]
    if obj.get("language") != "hu":
        return None
    if not isinstance(obj.get("id"), str) or len(obj["id"]) < 8:
        return None
    if obj.get("kind") not in ["article", "dialogue", "qa", "instructions", "code", "math", "reasoning"]:
        return None
    if not isinstance(obj.get("domain"), str) or len(obj["domain"]) < 2:
        return None
    if obj.get("difficulty") not in ["alap", "kozep", "halado", "elit"]:
        return None
    if not isinstance(obj.get("content"), str) or len(obj["content"]) < 800:
        return None
    safety = obj.get("safety")
    if not isinstance(safety, dict):
        return None
    if safety.get("pii") is not False:
        return None
    if safety.get("copyright_safe") is not True:
        return None
    if safety.get("hallucination_risk") not in ["low", "medium"]:
        return None
    if not isinstance(safety.get("notes"), str):
        return None
    if not looks_hungarian(obj["content"]):
        return None
    return obj

class RotatingJsonlWriter:
    def __init__(self, out_dir: str, prefix: str, bytes_per_file: int) -> None:
        self.out_dir = out_dir
        self.prefix = prefix
        self.bytes_per_file = bytes_per_file
        self.state_path = os.path.join(out_dir, f"{prefix}.state.json")
        self.file_index = 1
        self.bytes_written_current = 0
        self.fh = None
        safe_mkdir(out_dir)
        self._load_state()
        self._open_current()

    def _load_state(self) -> None:
        try:
            with open(self.state_path, "rb") as f:
                st = json.loads(f.read().decode("utf-8"))
            if isinstance(st, dict):
                self.file_index = int(st.get("file_index", 1))
        except Exception:
            self.file_index = 1

    def _save_state(self) -> None:
        st = {"file_index": self.file_index, "updated_at": now_utc_iso()}
        tmp = self.state_path + ".tmp"
        with open(tmp, "wb") as f:
            f.write(json.dumps(st, ensure_ascii=False).encode("utf-8"))
        os.replace(tmp, self.state_path)

    def _file_path(self, idx: int) -> str:
        return os.path.join(self.out_dir, f"{self.prefix}_{idx:06d}.jsonl")

    def _open_current(self) -> None:
        if self.fh is not None:
            try:
                self.fh.close()
            except Exception:
                pass
        path = self._file_path(self.file_index)
        self.fh = open(path, "ab")
        try:
            self.fh.seek(0, 2)
            self.bytes_written_current = self.fh.tell()
        except Exception:
            self.bytes_written_current = 0

    def _rotate(self) -> None:
        if self.fh is not None:
            try:
                self.fh.flush()
            except Exception:
                pass
        self.file_index += 1
        self._save_state()
        self._open_current()

    def write_obj(self, obj: Dict[str, Any]) -> Tuple[str, int, int]:
        line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8")
        if self.bytes_written_current + len(line) > self.bytes_per_file:
            self._rotate()
        self.fh.write(line)
        self.fh.flush()
        self.bytes_written_current += len(line)
        return self._file_path(self.file_index), self.file_index, self.bytes_written_current

def create_client(api_key: str, base_url: str, timeout_s: float) -> OpenAI:
    return OpenAI(api_key=api_key, base_url=base_url, timeout=httpx.Timeout(timeout_s))

def build_search_tool(tool_type: str, allowed_domains: List[str]) -> Dict[str, Any]:
    if tool_type == "web_search":
        if allowed_domains:
            return {"type": "web_search", "filters": {"allowed_domains": allowed_domains}}
        return {"type": "web_search"}
    if tool_type == "web_search_preview":
        if allowed_domains:
            return {"type": "web_search_preview", "filters": {"allowed_domains": allowed_domains}}
        return {"type": "web_search_preview"}
    if tool_type == "websearch":
        if allowed_domains:
            return {"type": "websearch", "filters": {"allowed_domains": allowed_domains}}
        return {"type": "websearch"}
    return {"type": tool_type}

def call_responses_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    tools: List[Dict[str, Any]],
    temperature: float,
    max_output_tokens: int,
    include: Optional[List[str]] = None
) -> Tuple[Dict[str, Any], List[str], Any]:
    request: Dict[str, Any] = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "text",
                        "text": "Kizárólag a megadott JSON sémának megfelelő objektumot adj vissza. Ne tegyél a kimenet elé vagy mögé semmilyen extra szöveget. A 'sources' mező kizárólag URL-eket tartalmazzon."
                    }
                ]
            },
            {
                "role": "user",
                "content": [{"type": "text", "text": prompt}]
            }
        ],
        "tools": tools,
        "text": {
            "format": {
                "type": "json_schema",
                "strict": True,
                "schema": schema
            }
        },
        "temperature": temperature,
        "max_output_tokens": max_output_tokens
    }
    if include:
        request["include"] = include
    resp = client.responses.create(**request)
    d = model_dump_any(resp)
    text = extract_text_from_response_dict(d)
    obj_raw = parse_json_lenient(text)
    if obj_raw is None:
        raise RuntimeError("responses.create nem JSON-t adott vissza")
    urls = extract_urls_from_response(resp)
    if "sources" not in obj_raw or not isinstance(obj_raw.get("sources"), list):
        obj_raw["sources"] = []
    merged: List[str] = []
    for u in obj_raw["sources"]:
        if is_url(u):
            merged.append(u)
    for u in urls:
        if is_url(u):
            merged.append(u)
    obj_raw["sources"] = list(dict.fromkeys(merged))
    obj = normalize_and_validate(obj_raw)
    if obj is None:
        raise RuntimeError("responses.create JSON nem felelt meg a sémának")
    return obj, obj.get("sources", []), resp

def call_chat_json_object(
    client: OpenAI,
    model: str,
    prompt: str,
    temperature: float,
    max_output_tokens: int
) -> Dict[str, Any]:
    messages = [
        {"role": "system", "content": "Kizárólag egyetlen JSON objektumot adj vissza, semmi mást."},
        {"role": "user", "content": prompt}
    ]
    completion = client.chat.completions.create(
        model=model,
        messages=messages,
        response_format={"type": "json_object"},
        temperature=temperature,
        max_tokens=max_output_tokens
    )
    content = completion.choices[0].message.content if completion and completion.choices else ""
    obj_raw = parse_json_lenient(content or "")
    if obj_raw is None:
        raise RuntimeError("chat.completions nem JSON-t adott vissza")
    if "sources" not in obj_raw or not isinstance(obj_raw.get("sources"), list):
        obj_raw["sources"] = []
    obj = normalize_and_validate(obj_raw)
    if obj is None:
        raise RuntimeError("chat.completions JSON nem felelt meg a sémának")
    return obj

def stable_id(task: Dict[str, str], seed: int, content: str) -> str:
    base = f"{task.get('kind','')}|{task.get('domain','')}|{task.get('difficulty','')}|{seed}|{sha256_hex(content)[:16]}"
    return sha256_hex(base)[:24]

def main() -> None:
    api_key = env_str("XAI_API_KEY", "XAIAPIKEY", "OPENAI_API_KEY")
    if not api_key:
        raise ValueError("API key nincs beállítva (XAI_API_KEY / XAIAPIKEY / OPENAI_API_KEY)")
    base_url = env_str("XAI_BASE_URL", "OPENAI_BASE_URL", default="") or ""
    model = env_str("XAI_MODEL", "MODEL", default="grok-4-1-fast-reasoning") or "grok-4-1-fast-reasoning"
    out_dir = env_str("OUT_DIR", default="datasets_hu_pretrain") or "datasets_hu_pretrain"
    prefix = env_str("FILE_PREFIX", default="hu_pretrain") or "hu_pretrain"
    bytes_per_file = env_int("BYTES_PER_FILE", 1048576)
    sleep_s = env_float("SLEEP_SECONDS", 0.15)
    temperature = env_float("TEMPERATURE", 0.2)
    max_output_tokens = env_int("MAX_OUTPUT_TOKENS", 8192)
    timeout_s = env_float("HTTP_TIMEOUT_SECONDS", 180.0)
    retries = env_int("RETRIES_PER_ITEM", 2)
    require_sources_for_factual = env_int("REQUIRE_SOURCES_FACTUAL", 1) == 1
    require_sources_for_all = env_int("REQUIRE_SOURCES_ALL", 0) == 1
    min_sources = env_int("MIN_SOURCES", 2)
    target_chars_min = env_int("TARGET_CHARS_MIN", 1200)
    target_chars_max = env_int("TARGET_CHARS_MAX", 3500)
    search_tool_mode = (env_str("SEARCH_TOOL", default="auto") or "auto").strip().lower()
    allowed_domains = env_csv("SEARCH_ALLOWED_DOMAINS")
    max_output_tokens = clamp_int(max_output_tokens, 1024, 65536)
    retries = clamp_int(retries, 0, 6)
    min_sources = clamp_int(min_sources, 1, 10)
    if target_chars_min < 900:
        target_chars_min = 900
    if target_chars_max < target_chars_min:
        target_chars_max = target_chars_min + 300

    seed_base = env_int("SEED", int(time.time()))
    rng = random.Random(seed_base)

    safe_mkdir(out_dir)
    client = create_client(api_key=api_key, base_url=base_url, timeout_s=timeout_s)
    writer = RotatingJsonlWriter(out_dir=out_dir, prefix=prefix, bytes_per_file=bytes_per_file)
    schema = build_schema()
    catalog = make_task_catalog()

    produced = 0
    consecutive_failures = 0
    backoff = 1.0

    print(f"START {now_utc_iso()} base_url={base_url} model={model} out_dir={out_dir} bytes_per_file={bytes_per_file} max_output_tokens={max_output_tokens}", flush=True)

    while True:
        seed = rng.randrange(0, 2000000000)
        task = catalog[rng.randrange(0, len(catalog))]
        factual = is_factual_domain(task["domain"])
        require_sources = require_sources_for_all or (require_sources_for_factual and factual)

        prompt = build_prompt(
            task=task,
            seed=seed,
            require_sources=require_sources,
            min_sources=min_sources,
            target_chars_min=target_chars_min,
            target_chars_max=target_chars_max
        )

        tool_candidates: List[str] = []
        if require_sources:
            if search_tool_mode == "auto":
                tool_candidates = ["web_search", "web_search_preview", "websearch"]
            else:
                tool_candidates = [search_tool_mode]
        else:
            tool_candidates = []

        include = ["web_search_call.action.sources"]

        print(f"REQ {now_utc_iso()} n={produced+1} kind={task['kind']} domain={task['domain']} diff={task['difficulty']} require_sources={str(require_sources).lower()}", flush=True)

        try:
            obj: Optional[Dict[str, Any]] = None
            resp_sources: List[str] = []
            gen_mode = "responses_structured"
            last_err: Optional[Exception] = None

            attempt = 0
            max_attempts = max(1, retries + 1)

            while attempt < max_attempts:
                attempt += 1
                try_tools = []
                if require_sources:
                    tool_type = tool_candidates[min(attempt - 1, len(tool_candidates) - 1)] if tool_candidates else "web_search"
                    try_tools = [build_search_tool(tool_type, allowed_domains)]
                try:
                    obj1, s1, _ = call_responses_structured(
                        client=client,
                        model=model,
                        prompt=prompt,
                        schema=schema,
                        tools=try_tools,
                        temperature=temperature,
                        max_output_tokens=max_output_tokens,
                        include=include if require_sources else None
                    )
                    obj = obj1
                    resp_sources = s1
                except Exception as e1:
                    last_err = e1
                    if require_sources:
                        continue
                    obj = None
                    try:
                        obj2 = call_chat_json_object(
                            client=client,
                            model=model,
                            prompt=prompt,
                            temperature=temperature,
                            max_output_tokens=max_output_tokens
                        )
                        obj = obj2
                        resp_sources = obj2.get("sources", []) if isinstance(obj2, dict) else []
                        gen_mode = "chat_json_object_fallback"
                    except Exception as e2:
                        last_err = e2
                        obj = None
                        continue

                if obj is None:
                    continue

                if require_sources:
                    srcs = obj.get("sources", []) if isinstance(obj.get("sources", []), list) else []
                    srcs = [u for u in srcs if is_url(u)]
                    obj["sources"] = srcs
                    if len(srcs) < min_sources:
                        prompt = prompt + f"\nKritikus követelmény: a 'sources' mezőben legalább {min_sources} darab URL legyen."
                        obj = None
                        continue

                break

            if obj is None:
                raise RuntimeError(repr(last_err) if last_err is not None else "ismeretlen hiba")

            content = obj["content"]
            sid = obj.get("id")
            if not isinstance(sid, str) or len(sid) < 8:
                sid = stable_id(task, seed, content)
            sources_final = obj.get("sources", []) if isinstance(obj.get("sources", []), list) else []
            sources_final = [u for u in sources_final if is_url(u)]
            obj_out: Dict[str, Any] = {
                "id": sid,
                "kind": obj["kind"],
                "language": "hu",
                "domain": obj["domain"],
                "difficulty": obj["difficulty"],
                "sources": sources_final,
                "citations_count": int(len(sources_final)),
                "content": content,
                "safety": obj["safety"],
                "meta": {
                    "generated_at": now_utc_iso(),
                    "seed": seed,
                    "generator": "jaide_dataset_builder",
                    "checksum_sha256": sha256_hex(content),
                    "require_sources": bool(require_sources),
                    "mode": gen_mode
                }
            }

            path, idx, b = writer.write_obj(obj_out)
            produced += 1
            consecutive_failures = 0
            backoff = 1.0
            print(f"OK {now_utc_iso()} n={produced} file={os.path.basename(path)} file_index={idx} file_bytes={b} citations_count={obj_out['citations_count']}", flush=True)

            if sleep_s > 0:
                time.sleep(sleep_s)

        except KeyboardInterrupt:
            print(f"STOP {now_utc_iso()} produced={produced}", flush=True)
            break
        except Exception as e:
            consecutive_failures += 1
            et = repr(e)
            print(f"ERR {now_utc_iso()} failures={consecutive_failures} backoff={backoff:.2f}s error={et}", file=sys.stderr, flush=True)
            if consecutive_failures >= 3:
                backoff = min(backoff * 1.8, 60.0)
            time.sleep(backoff)

